var FormWizard = function () {
    return {
        init: function () {
            function e(e) {
                return e.id ? "<img class='flag' src='../../assets/global/img/flags/" + e.id.toLowerCase() + ".png'/>&nbsp;&nbsp;" + e.text : e.text
            } if (jQuery().bootstrapWizard) {
                $("#branch").select2({
                    tags: false
                });
                $("#language").select2({
                    tags: true,
                    tokenSearators: [',', '']
                });
                $("#segment").select2({
                    tags: false
                });
                $("#registrationDateType").select2({
                    tags: false
                });
                $("#publicationDateType").select2({
                    tags: false
                });


                var r = $("#submit_form"),
                    t = $(".alert-danger", r),
                    i = $(".alert-success", r);
                r.validate({
                    doNotHideMessage: !0,
                    errorElement: "span",
                    errorClass: "help-block help-block-error",
                    focusInvalid: !1,
                    rules: {
                        name: { minlength: 2, required: !0 },
                        branch: { required: !0 },
                        language: { required: !0 },
                        authors: { required: !0 },
                        segment: { range: [1, 50], required: !0 },
                        editionOfSegment: { minlength: 1, maxlength: 50, required: !0 },
                        editionNo: { range: [1, 50], minlength: 1, maxlength: 30, required: !0 },
                        publicationNo: { range: [1, 10], minlength: 1, maxlength: 10, required: !0 },
                        publicationQuantity: { range: [1, 50], minlength: 1, maxlength: 50, required: !0 },
                        publicationPages: { range: [10, 5000], minlength: 2, maxlength: 5000, required: !0 },
                        registrationDateType: { required: !0 },
                        registrationDate: { required: !0 },
                        publicationDateType: { required: !0 },
                        publicationYear: { range: [1, 4000], required: !0 },
                        country: { required: !0 },
                        supervisorFirstname: { required: !0, minlength: 3, maxlength: 50},
                        supervisorLastname: { required: !0, minlength: 3, maxlength: 50},
                        internalConflict: { required: !0, minlength: 3, maxlength: 50},
                        externalConflict: { required: !0, minlength: 3, maxlength: 50},
                        studentRegistrationYear: { required: !0, range: [1200, 4000] },
                        studentGraduationYear: { required: !0, range: [1200, 4000] },
                        defenceDate: { required: !0 },
                        mark: { required: !0, range: [0, 100] },
                        graduationPeriod: { required: !0, range: [1, 1000] }

                        
                    },
                    messages: {
                        "payment[]": {
                            required: "Please select at least one option",
                            minlength: jQuery.validator.format("Please select at least one option")
                        }
                    },
                    errorPlacement: function (e, r) { "gender" == r.attr("name") ? e.insertAfter("#form_gender_error") : "payment[]" == r.attr("name") ? e.insertAfter("#form_payment_error") : e.insertAfter(r) },
                    invalidHandler: function (e, r) {
                        i.hide(),
                            t.show(),
                            App.scrollTo(t, -200)
                    },
                    highlight: function (e) {
                        $(e).closest(".form-group").removeClass("has-success").addClass("has-error")
                    },
                    unhighlight: function (e) {
                        $(e).closest(".form-group").removeClass("has-error")
                    },
                    success: function (e) {
                        "gender" == e.attr("for") || "payment[]" == e.attr("for") ? (e.closest(".form-group").removeClass("has-error").addClass("has-success"), e.remove()) : e.addClass("valid").closest(".form-group").removeClass("has-error").addClass("has-success")
                    },
                    submitHandler: function (e) {
                        i.show(),
                            t.hide(),
                            e[0].submit()
                    }
                });
                var a = function () {
                    $("#tab4 .form-control-static", r).each(function () {
                        var e = $('[name="' + $(this).attr("data-display") + '"]', r);
                        if (e.is(":radio") && (e = $('[name="' + $(this).attr("data-display") + '"]:checked', r)), e.is(":text") || e.is("textarea")) $(this).html(e.val());
                        else if (e.is("select"))
                            $(this).html(e.find("option:selected").text());
                        else if (e.is(":radio") && e.is(":checked"))
                            $(this).html(e.attr("data-title"));
                        else if ("payment[]" == $(this).attr("data-display")) {
                            var t = [];
                            $('[name="payment[]"]:checked', r).each(function () {
                                t.push($(this).attr("data-title"))
                            }),
                                $(this).html(t.join("<br>"))
                        }
                    })
                },
                    o = function (e, r, t) {
                        var i = r.find("li").length, o = t + 1;
                        $(".step-title", $("#form_wizard_1")).text("Step " + (t + 1) + " of " + i),
                            jQuery("li", $("#form_wizard_1")).removeClass("done"); for (var n = r.find("li"), s = 0; t > s; s++)jQuery(n[s]).addClass("done"); 1 == o ? $("#form_wizard_1").find(".button-previous").hide() : $("#form_wizard_1").find(".button-previous").show(), o >= i ? ($("#form_wizard_1").find(".button-next").hide(), $("#form_wizard_1").find(".button-submit").show(), a()) : ($("#form_wizard_1").find(".button-next").show(), $("#form_wizard_1").find(".button-submit").hide()), App.scrollTo($(".page-title"))
                    };
                $("#form_wizard_1").bootstrapWizard({
                    nextSelector: ".button-next",
                    previousSelector: ".button-previous",
                    onTabClick: function (e, r, t, i) { return !1 },
                    onNext: function (e, a, n) {
                        return i.hide(), t.hide(), 0 == r.valid() ? !1 : void o(e, a, n)
                    },
                    onPrevious: function (e, r, a) {
                        i.hide(), t.hide(), o(e, r, a)
                    },
                    onTabShow: function (e, r, t) {

                        var i = r.find("li").length, a = t + 1, o = a / i * 100; $("#form_wizard_1").find(".progress-bar").css({ width: o + "%" })
                    }
                }), $("#form_wizard_1").find(".button-previous").hide(),
                    $("#form_wizard_1 .button-submit").click(function () {

                        var ISBN = $('#ISBN').val();
                        var DDC = $('#DDC').val();
                        var LLC = $('#LLC').val();
                        var name = $('#name').val();
                        var translator = $('#translator').val();
                        var branch = $('#branch').val();
                        var language = $('#language').val();
                        var description = $('#description').val();
                        var permission = true;

                        if (document.getElementById("referenceBook").checked) {
                            permission = false;
                        }
                        else {
                            permission = true;
                        }

                        var internal_conflict = $('#internalConflict').val();
                        var external_conflict = $('#externalConflict').val();

                        var supervisor_firstname = $('#supervisorFirstname').val();
                        var supervisor_lastname = $('#supervisorLastname').val();
                        var student_registration_year = $('#studentRegistrationYear').val();
                        var student_graduation_year = $('#studentGraduationYear').val();
                        var defence_date = $('#defenceDate').val();
                        var mark = $('#mark').val();
                        var graduation_period = $('#graduationPeriod').val();

                        var bookProperties = {
                            ISBN: ISBN,
                            DDC_classificationNo: DDC,
                            LLC_classificationNo: LLC,
                            publication_name: name,
                            translator: translator,
                            branch_id: branch,
                            publication_language: language,
                            publication_description: description,
                            permission: permission
                        };
                        
                        var authors = $('#select2-disabled-inputs-multiple').val();

                        var thesis = {
                            internal_conflict: internal_conflict,
                            external_conflict: external_conflict
                        }


                        var monographAndThesisTable = {
                            supervisor_firstname: supervisor_firstname,
                            supervisor_lastname: supervisor_lastname,
                            student_registration_year: student_registration_year,
                            student_graduation_year: student_graduation_year,
                            defence_data: defence_date,
                            mark: mark,
                            graduation_period: graduation_period
                        }

                        var editionsProperty = [];
                        $('#editionDetail tbody tr').each(function (row, tr) {
                            editionsProperty[row] = {
                                "No": $(tr).find('td:eq(0)').text(),
                                "bookName": $(tr).find('td:eq(1)').text(),
                                "segmentNo": $(tr).find('td:eq(2)').text(),
                                "editionNo": $(tr).find('td:eq(3)').text(),
                                "publicationQuantity": $(tr).find('td:eq(4)').text(),
                                "publicationPages": $(tr).find('td:eq(5)').text(),
                                "CDQuantity": $(tr).find('td:eq(6)').text(),
                                "registrationDateType": $(tr).find('td:eq(7)').text(),
                                "registrationDate": $(tr).find('td:eq(8)').text(),
                                "publicationDateType": $(tr).find('td:eq(9)').text(),
                                "publicationYear": $(tr).find('td:eq(10)').text(),
                                "publicationMonth": $(tr).find('td:eq(11)').text(),
                                "publicationDay": $(tr).find('td:eq(12)').text(),
                                "cupboardNo": $(tr).find('td:eq(13)').text(),
                                "cellNo": $(tr).find('td:eq(14)').text(),
                                
                            }
                        });
                        

                        // Send tableData to the controller using AJAX
                        $.ajax({
                            url: "/Thesis/ThesisRegistration",
                            type: 'POST',
                            contentType: 'application/json; charset=utf-8',
                            data: JSON.stringify({ editionsProperty: editionsProperty, authors: authors, thesis: thesis, monographAndThesisTable: monographAndThesisTable, bookProperties: bookProperties }),
                            success: function (response) {
                                if (response == "publication not saved") {
                                    swal("ستونزه رامنځته شوه!", "د یوې ستونزې له امله مو معلومات ثبت نشول، مهرباني وکړئ معلومات مو دقیق داخل کړئ" , {
                                        icon: "error", buttons: "سمه ده"
                                    });
                                }
                                else if (response.redirectTo) {
                                    window.location.href = response.redirectTo;
                                }
                                else {
                                    swal("!Exception Occured", response , {
                                        icon: "info", buttons: "سمه ده"
                                    });
                                }
                            },
                            error: function (xhr, status, error) {
                                swal("ستونزه رامنځته شوه!", "Error: " + error, {
                                    icon: "error", buttons: "سمه ده"
                                });
                            }
                        });




                    }).hide(),
                    $("#country_list", r).change(function () {
                        r.validate().element($(this))
                    })
            }
        }
    }
}(); jQuery(document).ready(function () { FormWizard.init() });

